from inheritance_second import extend_labels
extend_labels(LABELS)

def render(lang,version):
 t=LABELS[lang]
 def check(key):return f'<label class="calc-check"><input type="checkbox" id="{key}"><span>{t[key+"Label"]}</span></label>'
 def number(key,value='0'):return f'<label class="calc-field" for="{key}"><span>{t[key+"Label"]}</span><input id="{key}" type="text" inputmode="numeric" value="{value}" autocomplete="off" maxlength="20"></label>'
 faqs=''.join(f'<details><summary>{t["faq"+str(i)]}</summary><p>{t["answer"+str(i)]}</p></details>' for i in range(1,5))
 return f'''<section class="calc-head wrap"><span class="eyebrow">{t['kicker']}</span><h1>{t['title']}</h1><p class="calc-lead">{t['lead']}</p><p>{t['scope']}</p><p class="calc-privacy">{t['privacy']}</p></section>
 <div class="calc-layout wrap"><form id="inheritance-form" class="calc-form" novalidate>
 <fieldset class="calc-card"><legend><span>01</span>{t['step1']}</legend><div class="calc-fields"><label class="calc-field" for="gender"><span>{t['gender']}</span><select id="gender"><option value="male">{t['male']}</option><option value="female">{t['female']}</option></select></label><div id="wives-field" hidden>{number('wives','1')}</div></div>{check('spouse')}</fieldset>
 <fieldset class="calc-card"><legend><span>02</span>{t['step2']}</legend><div class="calc-fields">{check('father')}{check('mother')}{number('sons')}{number('daughters')}</div><details id="hajib-details"><summary>{t['hajibTitle']}</summary><p class="calc-help">{t['hajibHelp']}</p><div class="calc-fields">{number('brothers')}{number('sisters')}</div>{check('siblingConditions')}<p class="calc-help">{t['hajibNote']}</p></details><details><summary>{t['limitsTitle']}</summary>{check('grandchildren')}{check('otherHeirs')}{check('special')}</details></fieldset>
 <fieldset class="calc-card calc-second" id="second-card"><legend><span>03</span>{t['secondTitle']}</legend><p class="calc-help">{t['secondHelp']}</p><h3>{t['siblingTitle']}</h3><p class="calc-help">{t['siblingHelp']}</p><div class="calc-fields">{number('fullBrothers')}{number('fullSisters')}{number('paternalBrothers')}{number('paternalSisters')}{number('maternalBrothers')}{number('maternalSisters')}</div><h3>{t['grandparentTitle']}</h3><p class="calc-help">{t['grandparentHelp']}</p><div class="calc-fields">{check('paternalGrandfather')}{check('paternalGrandmother')}{check('maternalGrandfather')}{check('maternalGrandmother')}</div>{check('siblingDescendants')}{check('remoteAncestors')}</fieldset><p id="second-excluded" class="calc-help" hidden>{t['secondExcluded']}</p>
 <fieldset class="calc-card"><legend><span>04</span>{t['step3']}</legend>{check('amountMode')}<div id="amount-fields" hidden><label class="calc-field" for="currency"><span>{t['currencyLabel']}</span><select id="currency"><option value="toman">{t['toman']}</option><option value="rial">{t['rial']}</option></select></label><div class="calc-fields">{number('gross','')}{number('costs')}{number('debts')}{number('bequest')}</div><p class="calc-help">{t['moneyHelp']}</p></div></fieldset>
 <div id="calc-error" class="calc-error" role="alert" hidden></div><div class="calc-actions"><button class="button primary" type="submit">{t['calculate']}</button><button class="calc-reset" type="reset">{t['reset']}</button></div></form>
 <aside class="calc-result-panel" aria-label="{t['resultTitle']}"><div class="calc-result-top"><span class="eyebrow">{t['resultTitle']}</span><span class="calc-badge">DAADER</span></div><div id="calc-empty"><h2>{t['empty']}</h2><p>{t['exampleLabel']}</p><div class="calc-examples"><button type="button" data-example="daughter">{t['example1']}</button><button type="button" data-example="son">{t['example2']}</button><button type="button" data-example="second">{t['example3']}</button></div></div><p id="calc-stale" role="status" hidden>{t['stale']}</p><div id="calc-result" hidden><div id="calc-net" class="calc-net" hidden></div><div id="calc-chart" class="calc-chart" aria-hidden="true"></div><div class="calc-table-wrap"><table><caption class="sr-only">{t['resultTitle']}</caption><thead><tr><th scope="col">{t['who']}</th><th scope="col">{t['fraction']}</th><th scope="col">{t['percent']}</th><th scope="col" class="calc-money" hidden>{t['money']}</th></tr></thead><tbody id="calc-rows"></tbody><tfoot><tr><th scope="row">{t['total']}</th><td><bdi>1</bdi></td><td id="calc-total-percent"></td><td id="calc-total-money" class="calc-money" hidden></td></tr></tfoot></table></div><p class="calc-help">{t['rounding']}</p><div class="calc-notes"><h3>{t['notesTitle']}</h3><ul id="calc-notes"></ul></div><button type="button" id="calc-copy" class="button">{t['copy']}</button><p id="copy-status" role="status" class="calc-help"></p></div><div class="calc-contact"><h3>{t['contactTitle']}</h3><p>{t['contactText']}</p><a class="text-link" href="https://wa.me/989123084826" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a></div></aside></div>
 <section class="calc-faq wrap"><h2>{t['faqTitle']}</h2>{faqs}<div class="calc-legal"><h3>{t['sources']}</h3><p>{t['sourceText']}</p><a class="text-link" href="https://nezamat.ir/قانون-مدنی/" target="_blank" rel="noopener noreferrer">{t['sourceLink']} ↗</a><p>{t['assumption']}</p></div></section><noscript><p class="wrap">{t['noscript']}</p></noscript><script type="application/json" id="calc-labels">{json.dumps(t,ensure_ascii=False).replace('<',chr(92)+'u003c')}</script><script src="/assets/inheritance-engine.js?v={version}" defer></script><script src="/assets/inheritance-ui.js?v={version}-reset" defer></script>'''
